//
// Ohne Abhaengigkeit, 1:1 in einen n8n-Code-Node kopierbar. Eingabe wie von values.get mit
// UNFORMATTED_VALUE/SERIAL_NUMBER: erste Zeile Kopf, dann eine Zeile je Anlage. Die Kopfzeile muss GENAU AN_SPALTEN
// sein (Reihenfolge eingeschlossen) - geschrieben wird spaltenweise, eine verschobene Spalte schriebe in die falsche
// Zelle. Sonst ok=false und nichts wird gelesen (Abbruch vor jedem Schreiben, fail-closed).
// Daten werden JJJJ-MM-TT, Unlesbares "ungültig: <Text>"; ob ein Datum gilt, entscheidet entscheidung.js.
// Die Sicherungen stehen je an EINER markierten Stelle ("Sicherung ...") fuer die Gegenprobe durch Mutation.

var AN_SPALTEN = [
  'Anlagen-ID', 'Kunden-ID', 'Kunde', 'E-Mail', 'Anlage', 'Leistung des Betriebs', 'Adresse erhoben bei',
  'Widerspruchshinweis bei Erhebung', 'Einbaudatum', 'letzte Wartung', 'Intervall (Monate)', 'Pause', 'Pause Grund',
  'Werbewiderspruch', 'Widerspruch aufheben', 'nächste Fälligkeit', 'Status', 'Angebot am', 'Erinnerung am',
  'Thread-ID', 'Antwort', 'Antwort erledigt', 'Protokoll', 'Versandstatus klären',
];

function anText(v) {
  return v === undefined || v === null ? '' : String(v).trim();
}

function anDatum(v) {
  if (typeof v === 'number') {
    var d = seriennummerZuDatum(v);
    return d === null ? 'ungültig: ' + v : d;
  }
  var s = anText(v);
  if (s === '') return '';
  return /^\d{4}-\d{2}-\d{2}$/.test(s) ? s : 'ungültig: ' + s;
}

// leer -> null (Standardintervall), ganze Zahl oder Ziffernfolge -> Zahl, sonst NaN (entscheidung.js prueft 1-60).
function anIntervall(v) {
  if (typeof v === 'number') return v;
  var s = anText(v);
  if (s === '') return null;
  return /^\d+$/.test(s) ? Number(s) : NaN;
}

// Übernommen aus Mahnlauf bau/kern/stufen.js (Commit 61022e4), unverändert: pruefeKopfzeile stufenSperre
function pruefeKopfzeile(kopf, pflichtspalten) {
  var k = (kopf || []).map(function (s) { return String(s).trim(); });
  var fehlend = (pflichtspalten || []).filter(function (s) { return k.indexOf(s) < 0; });
  return { ok: fehlend.length === 0, fehlend: fehlend };
}

function stufenSperre(v) {
  if (v === true) return true;
  if (v === false || v === null || v === undefined) return false;
  var s = String(v).trim().toLowerCase();
  return s !== '' && s !== 'nein' && s !== 'false' && s !== '0';
}

// Übernommen aus Mahnlauf bau/kern/offene-posten.js (Commit 61022e4), unverändert: OP_TAG0 opZwei seriennummerZuDatum
var OP_TAG0 = Date.UTC(1899, 11, 30);

function opZwei(n) {
  return (n < 10 ? '0' : '') + n;
}

function seriennummerZuDatum(v) {
  if (typeof v !== 'number' || !isFinite(v) || v < 1) return null;
  var d = new Date(OP_TAG0 + Math.floor(v) * 86400000);
  return d.getUTCFullYear() + '-' + opZwei(d.getUTCMonth() + 1) + '-' + opZwei(d.getUTCDate());
}

// werte: [[Kopf...], [Zeile...], ...] -> { ok, fehlend, abweichend, anlagen: [...], dubletten: [Anlagen-ID] }
function leseAnlagen(werte) {
  var w = werte || [];
  var kopf = (w[0] || []).map(anText);
  var p = pruefeKopfzeile(kopf, AN_SPALTEN);
  var aus = { ok: true, fehlend: p.fehlend, abweichend: false, anlagen: [], dubletten: [] };
  // Sicherung Kopfzeile exakt: Anfang
  if (!p.ok || kopf.length !== AN_SPALTEN.length || kopf.some(function (s, i) { return s !== AN_SPALTEN[i]; })) {
    aus.ok = false;
    aus.abweichend = true;
    return aus;
  }
  // Sicherung Kopfzeile exakt: Ende
  var idx = {};
  AN_SPALTEN.forEach(function (s, i) { idx[s] = i; });
  var zaehl = {};
  w.slice(1).forEach(function (z, k) {
    if (!z || z.every(function (v) { return anText(v) === ''; })) return;
    var g = function (s) { return z[idx[s]]; };
    var a = {
      zeile: k + 2,
      anlagen_id: anText(g('Anlagen-ID')),
      kunden_id: anText(g('Kunden-ID')),
      kunde: anText(g('Kunde')),
      email: anText(g('E-Mail')),
      anlage: anText(g('Anlage')),
      leistung: anText(g('Leistung des Betriebs')),
      erhoben_bei: anText(g('Adresse erhoben bei')),
      hinweis_erhebung: anDatum(g('Widerspruchshinweis bei Erhebung')),
      einbaudatum: anDatum(g('Einbaudatum')),
      letzte_wartung: anDatum(g('letzte Wartung')),
      intervall: anIntervall(g('Intervall (Monate)')),
      pause: stufenSperre(g('Pause')),
      pause_grund: anText(g('Pause Grund')),
      werbewiderspruch: stufenSperre(g('Werbewiderspruch')),
      widerspruch_aufheben: anText(g('Widerspruch aufheben')),
      faelligkeit_zelle: anDatum(g('nächste Fälligkeit')),
      status: anText(g('Status')),
      angebot_am: anDatum(g('Angebot am')),
      erinnerung_am: anDatum(g('Erinnerung am')),
      thread_id: anText(g('Thread-ID')),
      antwort: anText(g('Antwort')),
      antwort_erledigt: anText(g('Antwort erledigt')).toLowerCase() === 'ja',
      versandstatus_klaeren: anText(g('Versandstatus klären')),
      mangel: [],
    };
    if (!a.anlagen_id) a.mangel.push('Anlagen-ID fehlt');
    if (!a.kunden_id) a.mangel.push('Kunden-ID fehlt');
    if (a.anlagen_id) zaehl[a.anlagen_id] = (zaehl[a.anlagen_id] || 0) + 1;
    aus.anlagen.push(a);
  });
  aus.dubletten = Object.keys(zaehl).filter(function (id) { return zaehl[id] > 1; });
  aus.anlagen.forEach(function (a) {
    if (a.anlagen_id && zaehl[a.anlagen_id] > 1) a.mangel.push('Anlagen-ID doppelt'); // Sicherung Dublette
  });
  return aus;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { AN_SPALTEN, leseAnlagen, seriennummerZuDatum };
}

// Wartungserinnerung, Kernlogik: Textbausteine mit geprueften Platzhaltern (BAUPLAN b "Textbausteine", d, e; Baustein 2).
//
// Ohne Abhaengigkeit, 1:1 in einen n8n-Code-Node kopierbar. Der Betrieb schreibt Betreff und Text je Art (Angebot,
// Erinnerung) selbst; der Code prueft jeden Platzhalter (fuellePlatzhalter aus dem Mahnlauf, byte-gleich; die Liste
// PLATZHALTER_ERLAUBT ist neu). Den Widerspruchshinweis setzt der CODE ein, nie der Betrieb und nie ein Aufrufer:
// jeder Text muss {widerspruch} genau einmal tragen (§ 7 Abs. 3 Nr. 4 UWG, Art. 21 Abs. 4 DSGVO - Arbeitsstand).
// Jeder Betreff traegt {vorgang}: die Suche im Gesendet-Ordner nach einem abgebrochenen Lauf findet eine Mail nur
// ueber den Betreff. Die KI formuliert keinen Text (Arbeitsregel 5).

var PLATZHALTER_ERLAUBT = ['kunde', 'anlage', 'faellig_monat', 'vorgang', 'firma', 'telefon', 'signatur', 'widerspruch'];

// Derselbe Wortlaut steht in widerspruch.js (dort wird er vor der Wortliste aus Antworten entfernt).
var WIDERSPRUCH_ABSATZ = 'Sie können der Verwendung Ihrer E-Mail-Adresse für Angebote dieser Art jederzeit widersprechen. Eine kurze Antwort auf diese Mail genügt; dafür entstehen Ihnen keine anderen als die Übermittlungskosten nach den Basistarifen.';

var TB_ARTEN = ['Angebot', 'Erinnerung'];
var TB_MONATE = ['Januar', 'Februar', 'März', 'April', 'Mai', 'Juni', 'Juli', 'August', 'September', 'Oktober', 'November', 'Dezember'];

// Übernommen aus Mahnlauf bau/kern/platzhalter.js (Commit 01c681b), unverändert: phTag formatiereDatum fuellePlatzhalter
function phTag(d) {
  var r = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(d));
  if (!r) throw new Error('Datum nicht im Format JJJJ-MM-TT: ' + d);
  var ms = Date.UTC(+r[1], +r[2] - 1, +r[3]);
  var x = new Date(ms);
  if (x.getUTCFullYear() !== +r[1] || x.getUTCMonth() !== +r[2] - 1 || x.getUTCDate() !== +r[3]) {
    throw new Error('kein Kalenderdatum: ' + d);
  }
  return ms / 86400000;
}

function formatiereDatum(iso) {
  phTag(iso);
  var t = String(iso).split('-');
  return t[2] + '.' + t[1] + '.' + t[0];
}

function fuellePlatzhalter(vorlage, werte) {
  var s = String(vorlage == null ? '' : vorlage);
  var fehler = [];
  var tiefe = 0;
  for (var i = 0; i < s.length; i++) {
    if (s[i] === '{') {
      if (tiefe > 0) fehler.push({ platzhalter: '', grund: 'verschachtelt' });
      tiefe++;
    } else if (s[i] === '}') {
      if (tiefe === 0) fehler.push({ platzhalter: '', grund: 'ungeschlossen' });
      else tiefe--;
    }
  }
  if (tiefe > 0) fehler.push({ platzhalter: '', grund: 'ungeschlossen' });
  var text = s.replace(/\{([^{}]*)\}/g, function (ganz, roh) {
    var name = roh.trim();
    if (PLATZHALTER_ERLAUBT.indexOf(name) < 0) {
      fehler.push({ platzhalter: name, grund: 'unbekannt' });
      return ganz;
    }
    var v = werte ? werte[name] : undefined;
    if (v === undefined || v === null || String(v).trim() === '') {
      fehler.push({ platzhalter: name, grund: 'leer' });
      return ganz;
    }
    return String(v);
  });
  if (fehler.length) return { ok: false, fehler: fehler };
  return { ok: true, text: text };
}

function tbText(v) {
  return v === undefined || v === null ? '' : String(v).trim();
}

// "2026-10-20" -> "Oktober 2026"
function faelligMonat(iso) {
  phTag(iso);
  var t = String(iso).split('-');
  return TB_MONATE[+t[1] - 1] + ' ' + t[0];
}

// Blatt "Textbausteine" (Rohwerte, Kopfzeile zuerst) -> { ok, fehler: [Text] }
function pruefeTextbausteine(werte) {
  var w = werte || [];
  var kopf = (w[0] || []).map(tbText);
  var i = { art: kopf.indexOf('Art'), betreff: kopf.indexOf('Betreff'), text: kopf.indexOf('Text') };
  if (i.art < 0 || i.betreff < 0 || i.text < 0) return { ok: false, fehler: ['Blatt Textbausteine ohne Spalte Art, Betreff oder Text'] };
  var fehler = [];
  var anzahl = {};
  var betreffe = {};
  var probe = {};
  PLATZHALTER_ERLAUBT.forEach(function (p) { probe[p] = 'x'; });
  w.slice(1).forEach(function (z) {
    if (!z || z.every(function (v) { return tbText(v) === ''; })) return;
    var art = tbText(z[i.art]);
    var b = tbText(z[i.betreff]);
    var t = z[i.text] === undefined || z[i.text] === null ? '' : String(z[i.text]);
    if (TB_ARTEN.indexOf(art) < 0) { fehler.push('unbekannte Art ' + art); return; }
    anzahl[art] = (anzahl[art] || 0) + 1;
    if (!/\{\s*vorgang\s*\}/.test(b)) fehler.push(art + ' – Betreff ohne {vorgang}'); // Sicherung Betreff mit Vorgang
    var n = (t.match(/\{\s*widerspruch\s*\}/g) || []).length;
    if (n !== 1) fehler.push(art + ' – Text muss {widerspruch} genau einmal enthalten, gefunden ' + n); // Sicherung Widerspruch in der Vorlage
    [b, t].forEach(function (v) {
      var r = fuellePlatzhalter(v, probe);
      if (!r.ok) r.fehler.forEach(function (f) { fehler.push(art + ' – Platzhalter ' + f.platzhalter + ' ' + f.grund); });
    });
    var norm = b.replace(/\{\s*([^{}]*?)\s*\}/g, '{$1}');
    if (betreffe[norm] && betreffe[norm] !== art) fehler.push(betreffe[norm] + ' und ' + art + ' – gleicher Betreff');
    else betreffe[norm] = art;
  });
  TB_ARTEN.forEach(function (a) { if (anzahl[a] !== 1) fehler.push(a + ' – ' + (anzahl[a] || 0) + '-mal statt einmal'); });
  return { ok: fehler.length === 0, fehler: fehler };
}

// Letzte Pruefung vor dem Senden: der feste Hinweis steht wortgleich im Text.
function hinweisEnthalten(text) {
  return String(text == null ? '' : text).indexOf(WIDERSPRUCH_ABSATZ) >= 0; // Sicherung Hinweis-Pruefung
}

// art: 'Angebot' | 'Erinnerung'; werte: Platzhalterwerte ohne widerspruch; blatt: Rohwerte "Textbausteine"
// -> { ok, betreff, text } oder { ok: false, fehler: [Text] }
function baueMail(art, werte, blatt) {
  var p = pruefeTextbausteine(blatt);
  if (!p.ok) return { ok: false, fehler: p.fehler };
  var w = blatt || [];
  var kopf = (w[0] || []).map(tbText);
  var z = w.slice(1).filter(function (x) { return x && tbText(x[kopf.indexOf('Art')]) === art; })[0];
  if (!z) return { ok: false, fehler: ['Art unbekannt ' + art] };
  var v = {};
  Object.keys(werte || {}).forEach(function (k) { v[k] = werte[k]; });
  v.widerspruch = WIDERSPRUCH_ABSATZ; // Sicherung Hinweis vom Code
  var rb = fuellePlatzhalter(tbText(z[kopf.indexOf('Betreff')]), v);
  var rt = fuellePlatzhalter(String(z[kopf.indexOf('Text')]), v);
  if (!rb.ok || !rt.ok) {
    return { ok: false, fehler: (rb.fehler || []).concat(rt.fehler || []).map(function (f) { return f.platzhalter + ' ' + f.grund; }) };
  }
  if (!hinweisEnthalten(rt.text)) return { ok: false, fehler: ['Widerspruchshinweis fehlt im Text'] };
  return { ok: true, betreff: rb.text, text: rt.text };
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { PLATZHALTER_ERLAUBT, WIDERSPRUCH_ABSATZ, faelligMonat, pruefeTextbausteine, baueMail, hinweisEnthalten, formatiereDatum };
}

// ==== Treiber, nicht Teil des Kerns (bau/werkzeuge/zz_bau_b678.py) ====

const r = $input.first().json;
if (r.statusCode !== 200) throw new Error('Hauptlauf - Tabelle nicht lesbar, HTTP ' + r.statusCode);
const vr = (r.body && r.body.valueRanges) || [];
const w = (vr[0] && vr[0].values) || [];
const an = leseAnlagen(w);
if (!an.ok) throw new Error('Tabellenaufbau falsch – Blatt Anlagen – ' + (an.fehlend.length ? 'Spalte fehlt ' + an.fehlend.join(', ') : 'Spalten in anderer Reihenfolge oder zusätzlich')
  + ' – nichts gelesen, nichts geschrieben');
const tb = pruefeTextbausteine((vr[1] && vr[1].values) || []);
const ein = $('Einstellungen prüfen').first().json;
return [{ json: { anlagen: an.anlagen, dubletten: an.dubletten, tb_fehler: tb.fehler, kopf: w[0], modus: ein.modus } }];

// Wartungserinnerung, Kernlogik: Faelligkeit, Zyklus, Sperre und Plan eines Laufs (BAUPLAN b, c 5-6, d; Baustein 2).
//
// Ohne Abhaengigkeit, 1:1 in einen n8n-Code-Node kopierbar. "heute" gibt es hier nicht - nur den Parameter stichtag
// (JJJJ-MM-TT, Europe/Berlin gemeint). Eingaben sind schon gelesen: Anlagen aus anlagen.js, Einstellungen aus
// einstellungen.js, Sperrzeilen aus der Data Table "wartung-sperre", Antworten aus antwort.js/widerspruch.js.
// Mails verschickt nur der Versand; hier entsteht nur der Plan. Ein Zyklus ist Anlagen-ID + naechste Faelligkeit.
// Die Sicherungen stehen je an EINER markierten Stelle ("Sicherung ..."), damit die Gegenprobe durch Auskommentieren
// sie gezielt treffen kann. Fehlermeldungen ohne ": " vor dem Kern (der Code-Node kuerzt bis zum ersten ": ").

var EN_MAIL = ['angebot', 'erinnerung'];
var EN_LEISTUNGEN = ['Einbau', 'Wartung', 'Reparatur'];
var EN_SPERRGRUENDE = ['Antwort', 'Wortliste', 'Zweifel', 'Betrieb'];
var EN_MODI = ['trocken', 'test', 'scharf'];

// Übernommen aus Mahnlauf bau/kern/stufen.js (Commit 61022e4), unverändert: stufenTag stufenIstDatum datumPlusTage tageZwischen stufenMailOk waehleEmpfaenger bestimmeStichtag
function stufenTag(d) {
  var r = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(d));
  if (!r) throw new Error('Datum nicht im Format JJJJ-MM-TT: ' + d);
  var j = +r[1];
  var m = +r[2];
  var t = +r[3];
  var ms = Date.UTC(j, m - 1, t);
  var x = new Date(ms);
  if (x.getUTCFullYear() !== j || x.getUTCMonth() !== m - 1 || x.getUTCDate() !== t) {
    throw new Error('kein Kalenderdatum: ' + d);
  }
  return ms / 86400000;
}

function stufenIstDatum(d) {
  try { stufenTag(d); return true; } catch (e) { return false; }
}

function datumPlusTage(datum, tage) {
  if (!Number.isInteger(tage)) throw new Error('Tage muss ganze Zahl sein: ' + tage);
  var x = new Date((stufenTag(datum) + tage) * 86400000);
  var z = function (n) { return (n < 10 ? '0' : '') + n; };
  return x.getUTCFullYear() + '-' + z(x.getUTCMonth() + 1) + '-' + z(x.getUTCDate());
}

function tageZwischen(von, bis) {
  return stufenTag(bis) - stufenTag(von);
}

function stufenMailOk(s) {
  return /^[^\s@,;<>"]+@[^\s@,;<>"]+\.[^\s@,;<>"]+$/.test(String(s == null ? '' : s).trim());
}

function waehleEmpfaenger(modus, kundenEmail, testempfaenger) {
  if (modus === 'trocken') return { senden: false, an: null, grund: 'Modus trocken' };
  // Sicherung Testempfänger: Anfang
  if (modus === 'test') {
    if (!stufenMailOk(testempfaenger)) return { senden: false, an: null, grund: 'Modus test ohne gültigen Testempfänger' };
    return { senden: true, an: String(testempfaenger).trim(), grund: 'Modus test: Testempfänger erzwungen' };
  }
  // Sicherung Testempfänger: Ende
  if (modus === 'scharf') {
    if (!stufenMailOk(kundenEmail)) return { senden: false, an: null, grund: 'E-Mail fehlt oder ungültig' };
    return { senden: true, an: String(kundenEmail).trim(), grund: '' };
  }
  return { senden: false, an: null, grund: 'Modus unbekannt: ' + modus };
}

function bestimmeStichtag(modus, stichtagEinstellung, heute) {
  stufenTag(heute);
  var s = String(stichtagEinstellung == null ? '' : stichtagEinstellung).trim();
  if (!s) return { stichtag: heute, hinweis: '' };
  if (modus === 'test' || modus === 'trocken') {
    stufenTag(s);
    return { stichtag: s, hinweis: '' };
  }
  return { stichtag: heute, hinweis: 'Stichtag im Modus ' + modus + ' ignoriert' };
}

function enText(v) {
  return v === undefined || v === null ? '' : String(v).trim();
}

function normalisiereMail(s) {
  return enText(s).toLowerCase();
}

// Kalendermonate addieren; faellt der Tag weg, gilt der Monatsletzte (31.01. + 1 = 28./29.02.).
function plusMonate(iso, monate) {
  stufenTag(iso);
  if (!Number.isInteger(monate)) throw new Error('Monate muss ganze Zahl sein – ' + monate);
  var t = String(iso).split('-');
  var m = +t[1] - 1 + monate;
  var jahr = +t[0] + Math.floor(m / 12);
  var monat = ((m % 12) + 12) % 12;
  var letzter = new Date(Date.UTC(jahr, monat + 1, 0)).getUTCDate();
  var z = function (n) { return (n < 10 ? '0' : '') + n; };
  return jahr + '-' + z(monat + 1) + '-' + z(Math.min(+t[2], letzter));
}

// Basis ist die letzte Wartung, sonst das Einbaudatum; Intervall der Anlage, leer -> Standardintervall; 1-60 Monate.
function naechsteFaelligkeit(a, standardintervall) {
  var iv = a.intervall === null || a.intervall === undefined || a.intervall === '' ? standardintervall : a.intervall;
  if (!Number.isInteger(iv) || iv < 1 || iv > 60) return { ok: false, grund: 'Intervall ungültig (' + a.intervall + ')' };
  var name = a.letzte_wartung ? 'letzte Wartung' : 'Einbaudatum';
  var basis = a.letzte_wartung ? a.letzte_wartung : a.einbaudatum;
  if (!basis) return { ok: false, grund: 'weder letzte Wartung noch Einbaudatum' };
  if (!stufenIstDatum(basis)) return { ok: false, grund: name + ' unlesbar' };
  return { ok: true, faelligkeit: plusMonate(basis, iv), basis: name };
}

function vorgangNummer(anlagenId, faelligkeit) {
  return enText(anlagenId) + '/' + String(faelligkeit).slice(0, 7);
}

// Zwei Zeilen fuer die Data Table: die Sperre gilt je Kunde UND je Adresse.
function sperrZeilen(kundenId, email, grund) {
  if (EN_SPERRGRUENDE.indexOf(grund) < 0) throw new Error('Sperrgrund unbekannt – ' + grund);
  var z = [];
  if (enText(kundenId)) z.push({ schluessel: 'widerspruch|kunde|' + enText(kundenId), aktion: 'gesperrt', grund: grund });
  if (normalisiereMail(email)) z.push({ schluessel: 'widerspruch|mail|' + normalisiereMail(email), aktion: 'gesperrt', grund: grund });
  return z;
}

// Data-Table-Zeilen nach id: "gesperrt" sperrt, "aufgehoben" hebt auf, die spaetere Zeile gewinnt.
function sperrZustand(zeilen) {
  var z = { kunden: {}, mails: {} };
  (zeilen || []).filter(function (r) { return r && typeof r.schluessel === 'string'; }).slice()
    .sort(function (a, b) { return Number(a.id) - Number(b.id); })
    .forEach(function (r) {
      var m = /^widerspruch\|(kunde|mail)\|(.+)$/.exec(r.schluessel);
      if (!m) return;
      var ziel = m[1] === 'kunde' ? z.kunden : z.mails;
      var k = m[1] === 'mail' ? normalisiereMail(m[2]) : m[2];
      if (r.aktion === 'gesperrt') ziel[k] = { grund: enText(r.grund) };
