    puffer = (puffer << 6) | v;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      aus.push((puffer >> bits) & 255);
      puffer &= (1 << bits) - 1;
    }
  }
  return aus;
}

function awUtf8(b) {
