  var i = 0;
  while (i < b.length) {
    var c = b[i++];
    if (c < 0x80) s += String.fromCharCode(c);
    else if (c >= 0xc0 && c < 0xe0 && i < b.length) s += String.fromCharCode(((c & 31) << 6) | (b[i++] & 63));
    else if (c >= 0xe0 && c < 0xf0 && i + 1 < b.length) s += String.fromCharCode(((c & 15) << 12) | ((b[i++] & 63) << 6) | (b[i++] & 63));
