  if (/^(?:iso-?8859-1|iso-?8859-15|latin-?1|windows-1252|cp1252|us-ascii|ascii)$/.test(z)) return awCp1252(b);
  return awUtf8(b);
}

function awKopfListe(headers, name) {
  var h = (headers || []).filter(function (x) { return x && String(x.name).toLowerCase() === name.toLowerCase(); })[0];
  return h ? String(h.value) : '';
}

function awKopf(msg, name) {
  return awKopfListe(msg && msg.payload && msg.payload.headers, name);
}

function awSuche(p, typ) {
  if (!p) return null;
  if (String(p.mimeType).toLowerCase() === typ && p.body && p.body.data && !p.filename) return p;
  var t = p.parts || [];
  for (var i = 0; i < t.length; i++) {
    var r = awSuche(t[i], typ);
    if (r) return r;
  }
  return null;
}

function awTeilText(p) {
  var m = /charset\s*=\s*"?([^";\s]+)/i.exec(awKopfListe(p.headers, 'Content-Type'));
  return dekodiere(p.body.data, m ? m[1] : '').replace(/\r\n?/g, '\n');
}

function awEntitaeten(s) {
  return s.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, function (ganz, e) {
    if (e[0] === '#') {
      var n = e[1] === 'x' || e[1] === 'X' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return n > 0 && n < 0x110000 ? String.fromCodePoint(n) : ganz;
    }
    return Object.prototype.hasOwnProperty.call(AW_ENTITAETEN, e) ? AW_ENTITAETEN[e] : ganz;
  });
}

// HTML -> Text: Zitate (Gmail, Outlook, blockquote) weg, Bloecke werden Zeilen, leere Zeilen zusammengezogen.
function htmlZuText(html) {
  var s = String(html == null ? '' : html);
  s = s.replace(/<(style|script|head)\b[\s\S]*?<\/\1\s*>/gi, '');
  s = s.replace(/<div\b[^>]*class="[^"]*gmail_quote[^"]*"[\s\S]*$/i, '');
  s = s.replace(/<div\b[^>]*id="(?:divRplyFwdMsg|appendonsend)"[\s\S]*$/i, '');
  var vorher;
  do {
    vorher = s;
    s = s.replace(/<blockquote\b[^>]*>(?:(?!<blockquote\b)[\s\S])*?<\/blockquote\s*>/i, '\n');
  } while (s !== vorher);
  s = s.replace(/<br\s*\/?>/gi, '\n').replace(/<\/?(?:p|div|li|tr|h[1-6]|table|ul|ol)\b[^>]*>/gi, '\n').replace(/<[^>]*>/g, '');
  s = awEntitaeten(s);
  return s.split('\n').map(function (z) { return z.trim(); }).filter(function (z) { return z !== ''; }).join('\n');
}

// Gmail-Nachricht -> { text, quelle: 'plain' | 'html' | null }; text/plain hat Vorrang.
function textAusNachricht(msg) {
  var p = msg && msg.payload;
  var plain = awSuche(p, 'text/plain');
  if (plain) return { text: awTeilText(plain), quelle: 'plain' };
  var html = awSuche(p, 'text/html');
  if (html) return { text: htmlZuText(awTeilText(html)), quelle: 'html' };
  return { text: '', quelle: null };
}

function awFolgt(z, i, re) {
  for (var k = i + 1; k <= i + 3 && k < z.length; k++) if (re.test(z[k].trim())) return true;
  return false;
}

// Schneidet ab dem ersten Zitatkopf ab und entfernt jede Zeile, die mit ">" beginnt.
function ohneZitat(text) {
  var z = String(text == null ? '' : text).replace(/\r\n?/g, '\n').split('\n');
  var ende = z.length;
  for (var i = 0; i < z.length; i++) {
    var l = z[i].trim();
    var n = (z[i + 1] || '').trim();
    if (/^Am\s.+\bschrieb\b.*:$/.test(l) || (/^Am\s.+\bschrieb\b/.test(l) && /:$/.test(n) && /[@<>]/.test(n))
      || /^On\s.+\bwrote:$/.test(l) || (/^On\s.+/.test(l) && /\bwrote:$/.test(n))
      || /^-{3,}\s*(?:Ursprüngliche Nachricht|Original Message|Weitergeleitete Nachricht|Forwarded message)\s*-{3,}/i.test(l)
      || (/^_{10,}$/.test(l) && /^(?:Von|From):/.test(n))
      || (/^(?:Von|From):\s/.test(l) && awFolgt(z, i, /^(?:Gesendet|Sent|Datum|Date):\s/))) {
      ende = i;
      break;
    }
  }
  return z.slice(0, ende).filter(function (x) { return !/^\s*>/.test(x); }).join('\n').replace(/\s+$/, '');
}

// Signatur ab "-- "; sonst ab dem letzten Schlussgruss, wenn danach hoechstens zehn Zeilen folgen und er nicht in der
// ersten Zeile steht. "Grüß Gott" ist eine Anrede, kein Schlussgruss.
function ohneSignatur(text) {
  var z = String(text == null ? '' : text).replace(/\r\n?/g, '\n').split('\n');
  for (var i = 0; i < z.length; i++) {
    if (z[i] === '-- ' || z[i] === '--') { z = z.slice(0, i); break; }
  }
  for (var k = z.length - 1; k > 0; k--) {
    var l = z[k].trim();
    if (AW_GRUSS.test(l) && !AW_ANREDE.test(l)) {
      if (z.slice(k + 1).filter(function (x) { return x.trim() !== ''; }).length <= 10) z = z.slice(0, k);
      break;
    }
  }
  return z.join('\n').replace(/\s+$/, '');
}

// Kontaktangaben -> Platzhalter. Reihenfolge: Mail, IBAN, Telefon, Anschrift, PLZ/Ort.
function maskiereKontakt(text) {
  var s = String(text == null ? '' : text);
  s = s.replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '<EMAIL>');
  s = s.replace(/\b[A-Z]{2}\d{2}(?:[ ]?[A-Z0-9]{4}){3,7}(?:[ ]?[A-Z0-9]{1,3})?\b/g, '<IBAN>');
  s = s.replace(/(?:\+\d{1,3}[ \t\-\/]*(?:\(0\)[ \t]*)?|\(0\d{1,5}\)[ \t\-\/]*|\b0\d{1,5}[ \t\-\/]*)\d(?:[ \t\-\/]?\d){4,}/g, '<TELEFON>');
  s = s.replace(/\b[A-ZÄÖÜ][A-Za-zÄÖÜäöüß\-]*(?:straße|strasse|str\.|weg|gasse|platz|allee|ring|damm|ufer)\s+\d+\s?[a-zA-Z]?\b/g, '<ANSCHRIFT>');
  s = s.replace(/\b\d{5}\s+[A-ZÄÖÜ][a-zäöüß]+(?:[ -][A-ZÄÖÜ][a-zäöüß]+)*/g, '<PLZ_ORT>');
  return s;
}

// Text fuer Claude -> { text, gekuerzt }. Ist er leer, ordnet der Workflow nicht ein (wie eine fehlende KI-Antwort).
function fuerKi(text) {
  var t = String(text == null ? '' : text);
  t = ohneZitat(t); // Sicherung Datensparsamkeit Zitat
  t = ohneSignatur(t); // Sicherung Datensparsamkeit Signatur
  t = maskiereKontakt(t); // Sicherung Datensparsamkeit Kontakt
  t = t.replace(/\n{3,}/g, '\n\n').trim();
  if (t.length > 2000) return { text: t.slice(0, 2000), gekuerzt: true };
  return { text: t, gekuerzt: false };
}

function textFuerWortliste(text) {
  return ohneZitat(text);
}

// Unzustellbar wird vor Abwesenheit geprueft (gemessene Koepfe: beide koennen Auto-Submitted tragen).
function artDerNachricht(msg) {
  var von = awKopf(msg, 'From').toLowerCase();
  var typ = String((msg && msg.payload && msg.payload.mimeType) || '').toLowerCase();
  if (/mailer-daemon|postmaster/.test(von) || typ === 'multipart/report'
    || /report-type=delivery-status/.test(awKopf(msg, 'Content-Type').toLowerCase())) return 'unzustellbar';
  var auto = awKopf(msg, 'Auto-Submitted').trim().toLowerCase();
  if ((auto && auto !== 'no') || awKopf(msg, 'X-Autoreply') || /auto[_-]reply/.test(awKopf(msg, 'Precedence').toLowerCase())
    || /^(?:automatische antwort|abwesenheit|out of office|autoreply|auto-reply)/i.test(awKopf(msg, 'Subject'))) return 'abwesenheit';
  return 'antwort';
}

// thread (threads.get) -> { erste_eigene_ms, antworten: [{ id, internalDate, art }] } nach internalDate aufsteigend.
// abMs (Teil B, 27.09.2026): Untergrenze fuer einen Thread OHNE eigene Mail, den die Vorgangssuche gefunden hat (Abmeldung per
// Klick, neue Mail mit dem Vorgang im Betreff) - die erste eigene Mail des gespeicherten Threads. Ohne abMs wie bisher: nichts.
function antwortenImThread(thread, abMs) {
  var ms = (thread && thread.messages) || [];
  var lab = function (m) { return (m && m.labelIds) || []; };
  var eigene = ms.filter(function (m) { return lab(m).indexOf('SENT') >= 0 && lab(m).indexOf('DRAFT') < 0; })
    .map(function (m) { return Number(m.internalDate); });
  var erste;
  if (eigene.length) erste = Math.min.apply(null, eigene);
  else if (typeof abMs === 'number' && isFinite(abMs)) erste = abMs; // Sicherung Untergrenze Nebenthread
  else return { erste_eigene_ms: null, antworten: [] };
  var antworten = ms.filter(function (m) {
    if (lab(m).indexOf('SENT') >= 0) return false; // Sicherung eigene Mail ausgenommen
    return lab(m).indexOf('DRAFT') < 0 && Number(m.internalDate) > erste;
  }).map(function (m) { return { id: m.id, internalDate: Number(m.internalDate), art: artDerNachricht(m) }; })
    .sort(function (a, b) { return a.internalDate - b.internalDate; }); // Sicherung Reihenfolge internalDate
  return { erste_eigene_ms: erste, antworten: antworten };
}

// Betreff einer Gmail-Nachricht (Teil B: die Wortliste prueft auch ihn - "Abmelden <Vorgang>" aus List-Unsubscribe).
function betreffDerNachricht(msg) {
  return awKopf(msg, 'Subject');
}

// Antworten eines Threads nach der Einordnung (je { gmail_id, internalDate, datum, art, klasse, eingeordnet, gesperrt })
// -> Stand der Anlage fuer planeLauf, oder null. Vorrang: Antwort vor Unzustellbar vor Abwesenheit; innerhalb der Art
// zaehlt die neueste nach internalDate - die Eingabe kommt in beliebiger Reihenfolge (Befund Baustein 1). Eine nicht
// eingeordnete oder gesperrte Antwort gilt fuer die ganze Anlage.
function antwortStand(liste) {
  var l = (liste || []).filter(function (x) { return x && x.art; }).slice()
    .sort(function (a, b) { return Number(a.internalDate) - Number(b.internalDate); }); // Sicherung Reihenfolge Antwortstand
  var art = ['antwort', 'unzustellbar', 'abwesenheit'].filter(function (t) {
    return l.some(function (x) { return x.art === t; });
  })[0];
  if (!art) return null;
  var neueste = l.filter(function (x) { return x.art === art; }).pop();
  var antw = l.filter(function (x) { return x.art === 'antwort'; });
  return { art: art, klasse: neueste.klasse || '', datum: neueste.datum || '',
    eingeordnet: antw.every(function (x) { return x.eingeordnet === true; }),
    gesperrt: antw.some(function (x) { return x.gesperrt === true; }), anzahl: l.length };
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    dekodiere, textAusNachricht, htmlZuText, ohneZitat, ohneSignatur, maskiereKontakt, fuerKi, textFuerWortliste,
    artDerNachricht, antwortenImThread, antwortStand, betreffDerNachricht,
  };
}

// Wartungserinnerung, Kernlogik: Widerspruch erkennen und Antworten einordnen (BAUPLAN c 4, d, e; Baustein 2).
//
// Ohne Abhaengigkeit, 1:1 in einen n8n-Code-Node kopierbar. Reihenfolge: zuerst die Wortliste, OHNE KI - so haengt die
// Sperre nicht an der Erreichbarkeit der API. Nur ohne Treffer fragt der Workflow Claude (kiAnfrage; Antwortform mit
// Structured Outputs gemessen in Baustein 1, Lauf 6600). Im Zweifel am Widerspruch wird gesperrt: fehlende oder
// ungueltige Einordnung und jeder Widerspruchsverdacht; unsicher nur zwischen den anderen Klassen wird zurueckgestellt. Die KI-Antwort ist ein Schema aus drei Feldern und erreicht nie
// einen Mailtext. Der Text, der hier ankommt, ist schon gekuerzt und maskiert (antwort.js).
// Die Sicherungen stehen je an EINER markierten Stelle ("Sicherung ...") fuer die Gegenprobe durch Mutation.

// Derselbe Wortlaut steht in textbausteine.js (dort setzt ihn der Code in jede Mail). Arbeitsstand, keine Rechtsberatung.
var WIDERSPRUCH_ABSATZ = 'Sie können der Verwendung Ihrer E-Mail-Adresse für Angebote dieser Art jederzeit widersprechen. Eine kurze Antwort auf diese Mail genügt; dafür entstehen Ihnen keine anderen als die Übermittlungskosten nach den Basistarifen.';

var WI_MUSTER = [
  ['widersprechen', /widerspr/],
  ['keine Werbung/Mails', /keine\s+(?:weitere[nr]?\s+)?(?:werbung|werbemails?|e-?mails?|mails?|nachrichten|angebote|zusendungen)\b/],
  ['abmelden', /\b(?:abmelden|abbestellen|austragen|unsubscribe)\b|melden\s+sie\s+mich\s+(?:bitte\s+)?ab\b|tragen\s+sie\s+mich\s+(?:bitte\s+)?aus\b/],
  ['nicht mehr schreiben', /nicht\s+mehr\s+(?:an)?(?:schreiben|kontaktieren|mailen|zuschicken|schicken)\b/],
  ['nicht mehr kontaktieren', /(?:kontaktieren|anschreiben|schreiben|mailen)\s+sie\s+(?:mich|mir)\s+(?:bitte\s+)?(?:nicht|nie)\s+mehr/],
  ['Daten löschen', /(?:daten|adresse)\s+(?:bitte\s+)?loeschen|loeschen\s+sie\s+(?:bitte\s+)?(?:meine|mich)/],
];

// Teil A 2 (Entscheidung Elias 26.09.2026): feste Modellfassung statt Alias - die Tests und Messungen gelten fuer genau
// diese Fassung; ein Alias koennte ohne Zutun auf eine neue zeigen (README, Abschnitt Modell).
var KI_MODELL = 'claude-haiku-4-5-20251001';

var KI_KATEGORIEN = ['termin', 'rueckfrage', 'kein_interesse', 'widerspruch'];
var KI_SCHEMA = {
  type: 'object', additionalProperties: false, required: ['kategorie', 'sicher', 'widerspruch_moeglich'],
  properties: {
    kategorie: { type: 'string', enum: ['termin', 'rueckfrage', 'kein_interesse', 'widerspruch'] },
    sicher: { type: 'boolean' },
    widerspruch_moeglich: { type: 'boolean' },
  },
};
var KI_SYSTEM = 'Du ordnest die Antwort eines Kunden auf ein Wartungsangebot eines Heizungsbetriebs ein. Klassen: '
  + 'termin (der Kunde möchte einen Termin), rueckfrage (eine Frage zum Angebot), kein_interesse (lehnt dieses Angebot ab), '
  + 'widerspruch (will keine Werbung oder keine Mails mehr). sicher = false, wenn die Einordnung nicht eindeutig ist. '
  + 'widerspruch_moeglich = true, wenn der Text auch als Widerspruch gegen Werbung verstanden werden kann.';

function wiNorm(s) {
  return String(s == null ? '' : s).toLowerCase().replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue')
    .replace(/ß/g, 'ss').replace(/\s+/g, ' ').trim();
}

// -> Liste der getroffenen Muster (leer = kein Treffer). Der eigene Widerspruchshinweis zaehlt nicht.
function pruefeWortliste(text) {
  var t = wiNorm(text);
  t = t.split(wiNorm(WIDERSPRUCH_ABSATZ)).join(' '); // Sicherung eigener Hinweis ausgenommen
  return WI_MUSTER.filter(function (m) { return m[1].test(t); }).map(function (m) { return m[0]; });
}

function kiAnfrage(text) {
  var t = String(text == null ? '' : text).trim();
  if (!t) throw new Error('kein Antworttext fuer die Einordnung');
  return {
    model: KI_MODELL, max_tokens: 200, system: KI_SYSTEM, messages: [{ role: 'user', content: t }],
    output_config: { format: { type: 'json_schema', schema: JSON.parse(JSON.stringify(KI_SCHEMA)) } },
  };
}

// r: Ausgabe eines httpRequest 4.5 mit fullResponse/neverError ({statusCode, body}) oder ein Fehler-Item ({error}).
function pruefeKiAntwort(r) {
  var nein = function (g) { return { ok: false, kategorie: '', sicher: false, widerspruch_moeglich: true, grund: g }; };
  if (!r || typeof r !== 'object') return nein('keine Antwort');
  if (r.error) return nein('Verbindungsfehler');
  if (r.statusCode !== 200) return nein('HTTP ' + r.statusCode);
  var b = r.body || {};
  if (b.type !== 'message') return nein('keine Nachricht');
  if (b.stop_reason !== 'end_turn') return nein('stop_reason ' + b.stop_reason);
  var c = b.content || [];
  if (c.length !== 1 || !c[0] || c[0].type !== 'text') return nein('nicht genau ein Textblock');
  var j;
  try { j = JSON.parse(c[0].text); } catch (x) { return nein('kein JSON'); }
  if (!j || typeof j !== 'object' || Array.isArray(j)) return nein('kein Objekt');
  var felder = Object.keys(j).sort().join(',');
  if (felder !== 'kategorie,sicher,widerspruch_moeglich') return nein('Felder ' + felder);
  if (KI_KATEGORIEN.indexOf(j.kategorie) < 0) return nein('Kategorie unbekannt');
  if (typeof j.sicher !== 'boolean' || typeof j.widerspruch_moeglich !== 'boolean') return nein('Feldtyp');
  return { ok: true, kategorie: j.kategorie, sicher: j.sicher, widerspruch_moeglich: j.widerspruch_moeglich, grund: '' };
}

// x = { text: Text fuer die Wortliste (ohne Zitat), ki_an: Einstellung "KI-Einordnung" = an, ki: Antwort oder null }
// -> { gesperrt, grund (Antwort | Wortliste | Zweifel | ''), klasse, ki_noetig }
function ordneEin(x) {
  var treffer = pruefeWortliste(x.text);
  // Sicherung Wortliste vor der KI: Anfang
  if (treffer.length) return { gesperrt: true, grund: 'Wortliste', klasse: 'widerspruch', ki_noetig: false };
  // Sicherung Wortliste vor der KI: Ende
  if (!x.ki_an) return { gesperrt: false, grund: '', klasse: 'bitte lesen', ki_noetig: false };
  if (x.ki === null || x.ki === undefined) return { gesperrt: false, grund: '', klasse: '', ki_noetig: true };
  var k = pruefeKiAntwort(x.ki);
  if (!k.ok) return { gesperrt: true, grund: 'Zweifel', klasse: 'nicht eingeordnet', ki_noetig: false, ki_fehler: true, ki_grund: k.grund }; // Sicherung KI fehlt
  if (k.kategorie === 'widerspruch') return { gesperrt: true, grund: 'Antwort', klasse: 'widerspruch', ki_noetig: false }; // Sicherung Klasse Widerspruch
  if (k.widerspruch_moeglich) return { gesperrt: true, grund: 'Zweifel', klasse: k.kategorie, ki_noetig: false }; // Sicherung im Zweifel sperren
  // Teil A 27.09.2026 (Elias): "im Zweifel sperren" gilt nur fuer Zweifel am Widerspruch. Unsicher nur zwischen termin,
  // rueckfrage und kein_interesse -> zurueckgestellt: keine Sperre, Aufgabe "bitte lesen"; bis "Antwort erledigt" = ja geht
  // keine automatische Mail an den Kunden (Sicherung offene Antwort in entscheidung.js).
  if (!k.sicher) return { gesperrt: false, grund: '', klasse: 'unklar', ki_klasse: k.kategorie, ki_noetig: false }; // Sicherung unsicher zurueckstellen
  return { gesperrt: false, grund: '', klasse: k.kategorie, ki_noetig: false };
}

// Aufgabe fuer die Sammelmeldung (E7: ein Widerspruch wird vom Betrieb bestaetigt, nie automatisch).
function aufgabe(klasse) {
  if (klasse === 'termin') return 'Termin gewünscht – Kunde anrufen und Termin vereinbaren';
  if (klasse === 'rueckfrage') return 'Rückfrage – beantworten';
  if (klasse === 'kein_interesse') return 'kein Interesse – zur Kenntnis';
  if (klasse === 'widerspruch') return 'Widerspruch – gesperrt; dem Kunden den Widerspruch schriftlich bestätigen (Art. 12 Abs. 3 DSGVO, innerhalb eines Monats)';
  if (klasse === 'unklar') return 'Antwort unklar – bitte lesen und selbst einordnen; bis „Antwort erledigt“ = ja keine automatische Mail an den Kunden';
  return 'Antwort bitte lesen und selbst einordnen';
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { WIDERSPRUCH_ABSATZ, KI_MODELL, KI_SCHEMA, KI_SYSTEM, pruefeWortliste, kiAnfrage, pruefeKiAntwort, ordneEin, aufgabe };
}

// Wartungserinnerung, Kernlogik: Faelligkeit, Zyklus, Sperre und Plan eines Laufs (BAUPLAN b, c 5-6, d; Baustein 2).
//
// Ohne Abhaengigkeit, 1:1 in einen n8n-Code-Node kopierbar. "heute" gibt es hier nicht - nur den Parameter stichtag
// (JJJJ-MM-TT, Europe/Berlin gemeint). Eingaben sind schon gelesen: Anlagen aus anlagen.js, Einstellungen aus
// einstellungen.js, Sperrzeilen aus der Data Table "wartung-sperre", Antworten aus antwort.js/widerspruch.js.
// Mails verschickt nur der Versand; hier entsteht nur der Plan. Ein Zyklus ist Anlagen-ID + naechste Faelligkeit.
// Die Sicherungen stehen je an EINER markierten Stelle ("Sicherung ..."), damit die Gegenprobe durch Auskommentieren
// sie gezielt treffen kann. Fehlermeldungen ohne ": " vor dem Kern (der Code-Node kuerzt bis zum ersten ": ").

var EN_MAIL = ['angebot', 'erinnerung'];
var EN_LEISTUNGEN = ['Einbau', 'Wartung', 'Reparatur'];
var EN_SPERRGRUENDE = ['Antwort', 'Wortliste', 'Zweifel', 'Betrieb'];
var EN_MODI = ['trocken', 'test', 'scharf'];

// Übernommen aus Mahnlauf bau/kern/stufen.js (Commit 61022e4), unverändert: stufenTag stufenIstDatum datumPlusTage tageZwischen stufenMailOk waehleEmpfaenger bestimmeStichtag
function stufenTag(d) {
  var r = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(d));
  if (!r) throw new Error('Datum nicht im Format JJJJ-MM-TT: ' + d);
  var j = +r[1];
  var m = +r[2];
  var t = +r[3];
  var ms = Date.UTC(j, m - 1, t);
  var x = new Date(ms);
  if (x.getUTCFullYear() !== j || x.getUTCMonth() !== m - 1 || x.getUTCDate() !== t) {
    throw new Error('kein Kalenderdatum: ' + d);
  }
  return ms / 86400000;
}

function stufenIstDatum(d) {
  try { stufenTag(d); return true; } catch (e) { return false; }
}

function datumPlusTage(datum, tage) {
  if (!Number.isInteger(tage)) throw new Error('Tage muss ganze Zahl sein: ' + tage);
  var x = new Date((stufenTag(datum) + tage) * 86400000);
  var z = function (n) { return (n < 10 ? '0' : '') + n; };
  return x.getUTCFullYear() + '-' + z(x.getUTCMonth() + 1) + '-' + z(x.getUTCDate());
}

function tageZwischen(von, bis) {
  return stufenTag(bis) - stufenTag(von);
}

function stufenMailOk(s) {
  return /^[^\s@,;<>"]+@[^\s@,;<>"]+\.[^\s@,;<>"]+$/.test(String(s == null ? '' : s).trim());
}

function waehleEmpfaenger(modus, kundenEmail, testempfaenger) {
  if (modus === 'trocken') return { senden: false, an: null, grund: 'Modus trocken' };
  // Sicherung Testempfänger: Anfang
  if (modus === 'test') {
    if (!stufenMailOk(testempfaenger)) return { senden: false, an: null, grund: 'Modus test ohne gültigen Testempfänger' };
    return { senden: true, an: String(testempfaenger).trim(), grund: 'Modus test: Testempfänger erzwungen' };
  }
  // Sicherung Testempfänger: Ende
  if (modus === 'scharf') {
    if (!stufenMailOk(kundenEmail)) return { senden: false, an: null, grund: 'E-Mail fehlt oder ungültig' };
    return { senden: true, an: String(kundenEmail).trim(), grund: '' };
  }
  return { senden: false, an: null, grund: 'Modus unbekannt: ' + modus };
}

function bestimmeStichtag(modus, stichtagEinstellung, heute) {
  stufenTag(heute);
  var s = String(stichtagEinstellung == null ? '' : stichtagEinstellung).trim();
  if (!s) return { stichtag: heute, hinweis: '' };
  if (modus === 'test' || modus === 'trocken') {
    stufenTag(s);
    return { stichtag: s, hinweis: '' };
  }
  return { stichtag: heute, hinweis: 'Stichtag im Modus ' + modus + ' ignoriert' };
}

function enText(v) {
  return v === undefined || v === null ? '' : String(v).trim();
}

function normalisiereMail(s) {
  return enText(s).toLowerCase();
}

// Kalendermonate addieren; faellt der Tag weg, gilt der Monatsletzte (31.01. + 1 = 28./29.02.).
function plusMonate(iso, monate) {
  stufenTag(iso);
  if (!Number.isInteger(monate)) throw new Error('Monate muss ganze Zahl sein – ' + monate);
  var t = String(iso).split('-');
  var m = +t[1] - 1 + monate;
  var jahr = +t[0] + Math.floor(m / 12);
  var monat = ((m % 12) + 12) % 12;
  var letzter = new Date(Date.UTC(jahr, monat + 1, 0)).getUTCDate();
  var z = function (n) { return (n < 10 ? '0' : '') + n; };
  return jahr + '-' + z(monat + 1) + '-' + z(Math.min(+t[2], letzter));
}

// Basis ist die letzte Wartung, sonst das Einbaudatum; Intervall der Anlage, leer -> Standardintervall; 1-60 Monate.
function naechsteFaelligkeit(a, standardintervall) {
  var iv = a.intervall === null || a.intervall === undefined || a.intervall === '' ? standardintervall : a.intervall;
  if (!Number.isInteger(iv) || iv < 1 || iv > 60) return { ok: false, grund: 'Intervall ungültig (' + a.intervall + ')' };
  var name = a.letzte_wartung ? 'letzte Wartung' : 'Einbaudatum';
  var basis = a.letzte_wartung ? a.letzte_wartung : a.einbaudatum;
  if (!basis) return { ok: false, grund: 'weder letzte Wartung noch Einbaudatum' };
  if (!stufenIstDatum(basis)) return { ok: false, grund: name + ' unlesbar' };
  return { ok: true, faelligkeit: plusMonate(basis, iv), basis: name };
}

function vorgangNummer(anlagenId, faelligkeit) {
  return enText(anlagenId) + '/' + String(faelligkeit).slice(0, 7);
}

// Zwei Zeilen fuer die Data Table: die Sperre gilt je Kunde UND je Adresse.
function sperrZeilen(kundenId, email, grund) {
  if (EN_SPERRGRUENDE.indexOf(grund) < 0) throw new Error('Sperrgrund unbekannt – ' + grund);
  var z = [];
  if (enText(kundenId)) z.push({ schluessel: 'widerspruch|kunde|' + enText(kundenId), aktion: 'gesperrt', grund: grund });
  if (normalisiereMail(email)) z.push({ schluessel: 'widerspruch|mail|' + normalisiereMail(email), aktion: 'gesperrt', grund: grund });
  return z;
}

// Data-Table-Zeilen nach id: "gesperrt" sperrt, "aufgehoben" hebt auf, die spaetere Zeile gewinnt.
function sperrZustand(zeilen) {
  var z = { kunden: {}, mails: {} };
  (zeilen || []).filter(function (r) { return r && typeof r.schluessel === 'string'; }).slice()
    .sort(function (a, b) { return Number(a.id) - Number(b.id); })
    .forEach(function (r) {
      var m = /^widerspruch\|(kunde|mail)\|(.+)$/.exec(r.schluessel);
      if (!m) return;
      var ziel = m[1] === 'kunde' ? z.kunden : z.mails;
      var k = m[1] === 'mail' ? normalisiereMail(m[2]) : m[2];
      if (r.aktion === 'gesperrt') ziel[k] = { grund: enText(r.grund) };
      else if (r.aktion === 'aufgehoben') delete ziel[k];
    });
  return z;
}

function istGesperrt(a, sperre) {
  var s = sperre || { kunden: {}, mails: {} };
  var ueber = [];
  if (a.kunden_id && s.kunden[a.kunden_id]) ueber.push('kunde'); // Sicherung Sperre Kunden-ID
  if (normalisiereMail(a.email) && s.mails[normalisiereMail(a.email)]) ueber.push('mail'); // Sicherung Sperre E-Mail
  var zelle = false;
  if (a.werbewiderspruch === true) zelle = true; // Sicherung Sperre Zelle
  return { gesperrt: ueber.length > 0 || zelle, data_table: ueber.length > 0, zelle: zelle, ueber: ueber };
}

// § 7 Abs. 3 UWG (BAUPLAN e): Kundenbeziehung, eigene aehnliche Leistung, Hinweis bei Erhebung; dazu eine gueltige Adresse.
function pflichtFehlt(a, stichtag) {
  var f = [];
  if (EN_LEISTUNGEN.indexOf(enText(a.leistung)) < 0) f.push('Leistung des Betriebs');
  if (!enText(a.erhoben_bei)) f.push('Adresse erhoben bei');
  if (!stufenIstDatum(a.hinweis_erhebung) || tageZwischen(a.hinweis_erhebung, stichtag) < 0) f.push('Widerspruchshinweis bei Erhebung');
  if (!stufenMailOk(a.email)) f.push('E-Mail');
  return f;
}

// a: Anlage aus anlagen.js; k: { e: Einstellungen, stichtag, sperre: sperrZustand(...), antwort: null | { art, klasse, datum } }
function entscheideAnlage(a, k) {
  var e = k.e;
  var stichtag = k.stichtag;
  var d = {
    anlagen_id: a.anlagen_id, kunden_id: a.kunden_id, email_norm: normalisiereMail(a.email), zeile: a.zeile,
    aktion: '', grund: '', faelligkeit: '', vorgang: '', zyklus_neu: false, sperre_nachtragen: false, zelle_nachtragen: false,
    aufheben: null, antwort: null, antwort_offen: false, hinweise: [],
  };
  var neu = k.antwort || null;
  // Teil A 7: offen ist eine Antwort aus diesem Lauf (auch nicht eingeordnet) oder eine eingetragene ohne "Antwort erledigt";
  // ein neuer Zyklus schliesst die eingetragene (unten). Frueh endende Pfade behalten den Wert (sperrt, nie umgekehrt).
  d.antwort_offen = !!(neu && neu.art === 'antwort')
    || ((enText(a.antwort) !== '' || a.status === 'beantwortet') && a.antwort_erledigt !== true);
  var sp = istGesperrt(a, k.sperre);
  if (a.widerspruch_aufheben) {
    if (!sp.gesperrt) d.hinweise.push('Widerspruch aufheben ohne bestehende Sperre');
    else if (a.widerspruch_aufheben.length < 10) d.hinweise.push('Widerspruch aufheben – Grund fehlt oder ist zu kurz');
    else d.aufheben = { grund: a.widerspruch_aufheben };
  }
  if (sp.gesperrt) {
    d.aktion = 'gesperrt';
    d.grund = 'Werbewiderspruch';
    d.zelle_nachtragen = sp.data_table && !sp.zelle;
    d.sperre_nachtragen = sp.zelle && !sp.data_table;
    return d;
  }
  // Sicherung Pause: Anfang
  if (a.pause) {
    d.aktion = 'pausiert';
    d.grund = a.pause_grund || 'Pause';
    if (!a.pause_grund) d.hinweise.push('Pause ohne Grund');
    return d;
  }
  // Sicherung Pause: Ende
  var fehlt = pflichtFehlt(a, stichtag);
  // Sicherung Pflichtangaben: Anfang
  if (fehlt.length) {
    d.aktion = 'pflichtangabe';
    d.grund = fehlt.join(', ');
    d.hinweise.push('Pflichtangabe fehlt – ' + d.grund);
    return d;
  }
  // Sicherung Pflichtangaben: Ende
  if ((a.mangel || []).length) {
    d.aktion = 'mangel';
    d.grund = a.mangel.join(', ');
    d.hinweise.push(d.grund);
    return d;
  }
  var f = naechsteFaelligkeit(a, e.standardintervall);
  if (!f.ok) {
    d.aktion = 'mangel';
    d.grund = f.grund;
    d.hinweise.push(f.grund);
    return d;
  }
  d.faelligkeit = f.faelligkeit;
  d.vorgang = vorgangNummer(a.anlagen_id, f.faelligkeit);
  var z = { angebot_am: a.angebot_am, erinnerung_am: a.erinnerung_am, antwort: a.antwort, status: a.status };
  if (a.faelligkeit_zelle && a.faelligkeit_zelle !== f.faelligkeit && (z.angebot_am || z.erinnerung_am || z.antwort || z.status)) {
    d.zyklus_neu = true;
    z = { angebot_am: '', erinnerung_am: '', antwort: '', status: '' };
    d.antwort_offen = !!(neu && neu.art === 'antwort');
  }
  if ((z.angebot_am && !stufenIstDatum(z.angebot_am)) || (z.erinnerung_am && !stufenIstDatum(z.erinnerung_am))) {
    d.aktion = 'mangel';
    d.grund = 'Angebot am oder Erinnerung am unlesbar';
    d.hinweise.push(d.grund);
    return d;
  }
  if (neu && neu.art === 'unzustellbar') {
    d.aktion = 'unzustellbar';
    d.antwort = neu;
    d.hinweise.push('Mail unzustellbar – Adresse prüfen');
    return d;
  }
  if (neu && neu.art === 'antwort') {
    d.aktion = 'beantwortet';
    d.antwort = neu;
    return d;
  }
  if (neu && neu.art === 'abwesenheit') d.hinweise.push('Abwesenheitsnotiz vom ' + enText(neu.datum));
  if (z.status === 'unzustellbar') { d.aktion = 'unzustellbar'; return d; }
  if (z.status === 'beantwortet' || z.antwort) { d.aktion = 'beantwortet'; return d; }
  if (!z.angebot_am) {
    if (tageZwischen(stichtag, f.faelligkeit) > e.vorlauf) d.aktion = 'nicht_faellig';
    else if (tageZwischen(f.faelligkeit, stichtag) > e.nachlauf) {
      d.aktion = 'verpasst';
      d.hinweise.push('Fälligkeit ' + f.faelligkeit + ' verpasst – kein Angebot mehr, der Betrieb entscheidet');
    } else d.aktion = 'angebot';
    return d;
  }
  if (!z.erinnerung_am) {
    d.aktion = tageZwischen(z.angebot_am, stichtag) >= e.erinnerung_nach ? 'erinnerung' : 'wartet';
    return d;
  }
  if (tageZwischen(z.erinnerung_am, stichtag) >= e.antwortfenster) {
    d.aktion = 'abgeschlossen';
    if (tageZwischen(plusMonate(f.faelligkeit, 12), stichtag) >= 0) {
      d.hinweise.push('seit zwölf Monaten nach der Fälligkeit kein Wartungsdatum eingetragen');
    }
    return d;
  }
  d.aktion = 'wartet';
  return d;
}

function enStopp(d, aktion, grund) {
  d.aktion_geplant = d.aktion;
  d.aktion = aktion;
  d.grund = grund;
}

// p = { einstellungen, stichtag, anlagen, sperrzeilen, antworten: { Anlagen-ID: {art, klasse, datum} },
//       antworten_gelesen: true nur, wenn JEDER zu lesende Thread gelesen wurde, textbausteine_fehler: [Text] }
function planeLauf(p) {
  var e = p.einstellungen || {};
  [['vorlauf', 0, 365], ['nachlauf', 0, 365], ['erinnerung_nach', 1, 365], ['antwortfenster', 1, 365],
    ['antworten_lesen_bis', 1, 3650], ['standardintervall', 1, 60], ['hoechstzahl_mails', 0, 1000]].forEach(function (g) {
    var v = e[g[0]];
    if (!Number.isInteger(v) || v < g[1] || v > g[2]) throw new Error('Einstellung ungültig – ' + g[0]);
  });
  if (EN_MODI.indexOf(e.modus) < 0) throw new Error('Einstellung ungültig – Modus');
  stufenTag(p.stichtag);
  var sperre = sperrZustand(p.sperrzeilen);
  var antworten = p.antworten || {};
  var plan = { entscheidungen: [], versand: [], alarme: [], hinweise: [],
    mengenbremse: { gerissen: false, anzahl: 0, hoechstzahl: e.hoechstzahl_mails } };
  (p.anlagen || []).forEach(function (a) {
    var d = entscheideAnlage(a, { e: e, stichtag: p.stichtag, sperre: sperre, antwort: antworten[a.anlagen_id] || null });
    plan.entscheidungen.push(d);
    d.hinweise.forEach(function (h) { plan.hinweise.push({ anlagen_id: d.anlagen_id, text: h }); });
  });
  var mail = function (d) { return EN_MAIL.indexOf(d.aktion) >= 0; };

  // A3: ein Wert in "Versandstatus klären" haelt die anstehende Mail an; der Hauptlauf klaert mit der Data Table (klaerungsAuftrag).
  var anlMap = {};
  (p.anlagen || []).forEach(function (a) { if (!anlMap[a.anlagen_id]) anlMap[a.anlagen_id] = a; });
  plan.entscheidungen.forEach(function (d) {
    var w = enText((anlMap[d.anlagen_id] || {}).versandstatus_klaeren);
    if (!w || !mail(d)) return;
    d.klaer_schluessel = d.aktion + '|' + d.anlagen_id + '|' + d.faelligkeit;
    d.klaer_wert = w;
    enStopp(d, 'versandstatus', 'Versandstatus klären „' + w + '“ – kein Versand in diesem Lauf'); // Sicherung Versandstatus haelt an
  });

  // Sicherung Antwortstand frisch: Anfang
  if (p.antworten_gelesen !== true) {
    var n1 = 0;
    plan.entscheidungen.forEach(function (d) {
      if (mail(d)) { enStopp(d, 'antworten_ungelesen', 'Antworten nicht vollständig gelesen'); n1++; }
    });
    plan.alarme.push({ art: 'Antworten nicht gelesen', text: 'kein Versand in diesem Lauf, ' + n1 + ' Vorgänge zurückgestellt' });
  }
  // Sicherung Antwortstand frisch: Ende

  var tbf = p.textbausteine_fehler || [];
  // Sicherung Textbausteine: Anfang
  if (tbf.length) {
    plan.entscheidungen.forEach(function (d) { if (mail(d)) enStopp(d, 'textbausteine', 'Textbausteine ungültig'); });
    plan.alarme.push({ art: 'Textbausteine ungültig', text: tbf.join('; ') });
  }
  // Sicherung Textbausteine: Ende

  // Sicherung offene Antwort: Anfang
  var offenK = {};
  var offenM = {};
  plan.entscheidungen.forEach(function (d) {
    if (!d.antwort_offen) return;
    if (d.kunden_id) offenK[d.kunden_id] = d.anlagen_id;
    if (d.email_norm) offenM[d.email_norm] = d.anlagen_id;
  });
  plan.entscheidungen.forEach(function (d) {
    var bei = (d.kunden_id && offenK[d.kunden_id]) || (d.email_norm && offenM[d.email_norm]);
    if (mail(d) && bei) enStopp(d, 'antwort_offen', 'offene Antwort des Kunden (' + bei + ') – erst „Antwort erledigt“ = ja');
  });
  // Sicherung offene Antwort: Ende

  // Sicherung eine Mail je Kunde: Anfang
  var kunden = {};
  var adressen = {};
  // Auftrag 27.09.2026 nachmittags (A1): E6 gilt je Kalendertag (Europe/Berlin) - wer heute schon eine Mail bekam (Data Table,
  // heuteVersendet), bekommt keine zweite; die naechste Anlage kommt am naechsten Werktag. Im Modus trocken (ohne Data Table) je Lauf.
  // Sicherung Tagesgrenze: Anfang
  (p.heute_versendet || []).forEach(function (h) {
    if (enText(h.kunden_id)) kunden[enText(h.kunden_id)] = 'heute';
    if (normalisiereMail(h.email_norm)) adressen[normalisiereMail(h.email_norm)] = 'heute';
  });
  // Sicherung Tagesgrenze: Ende
  plan.entscheidungen.filter(mail).slice().sort(function (x, y) {
    if (x.faelligkeit !== y.faelligkeit) return x.faelligkeit < y.faelligkeit ? -1 : 1;
    return x.anlagen_id < y.anlagen_id ? -1 : x.anlagen_id > y.anlagen_id ? 1 : 0;
  }).forEach(function (d) {
    var schon = (d.kunden_id && kunden[d.kunden_id]) || (d.email_norm && adressen[d.email_norm]);
    if (schon) {
      enStopp(d, 'naechster_werktag', schon === 'heute' ? 'höchstens eine Mail je Kunde und Tag – heute schon eine Mail an diesen Kunden'
        : 'höchstens eine Mail je Kunde und Tag');
      return;
    }
    kunden[d.kunden_id] = true;
    adressen[d.email_norm] = true;
  });
  // Sicherung eine Mail je Kunde: Ende

  var anzahl = plan.entscheidungen.filter(mail).length;
  plan.mengenbremse.anzahl = anzahl;
  // Sicherung Mengenbremse: Anfang
  if (anzahl > e.hoechstzahl_mails) {
    plan.mengenbremse.gerissen = true;
    plan.entscheidungen.forEach(function (d) { if (mail(d)) enStopp(d, 'mengenbremse', 'Mengenbremse'); });
    plan.alarme.push({ art: 'Mengenbremse', text: anzahl + ' Mails fällig, Höchstzahl ' + e.hoechstzahl_mails });
  }
  // Sicherung Mengenbremse: Ende

  plan.versand = plan.entscheidungen.filter(mail);
  return plan;
}

// Baustein 5: Threads, deren Antworten dieser Lauf liest - nicht gesperrt (der Text eines gesperrten Kunden geht nicht mehr an
// die KI, Art. 21 Abs. 3 DSGVO), letzte eigene Mail hoechstens "Antworten lesen bis" Tage zurueck; ohne lesbares Datum wird
// gelesen (ein spaeter Widerspruch muss wirken). Teil B: je Eintrag der Vorgang fuer die Vorgangssuche (leer ohne Faelligkeit).
// Auftrag 27.09. nachmittags: Angebot ohne Thread-ID (etwa nach "Versandstatus klären") -> nur_suche mit Untergrenze ab_ms;
// alte Vorgaenge (A2) - versendet laut Data Table (zeilen), Versand hoechstens "Antworten lesen bis" Tage zurueck, und der
// gespeicherte Thread, wenn der Zyklus in diesem Lauf wechselt - mit alt: true (dort zaehlt nur ein Widerspruch).
function zuLesendeThreads(anlagen, sperre, stichtag, e, zeilen) {
  var aus = [];
  (anlagen || []).forEach(function (a) {
    if (istGesperrt(a, sperre).gesperrt) return; // Sicherung gesperrt nicht lesen
    var basis = { anlagen_id: a.anlagen_id, kunden_id: a.kunden_id, email_norm: normalisiereMail(a.email) };
    var f = naechsteFaelligkeit(a, e.standardintervall);
    var vorgang = f.ok ? vorgangNummer(a.anlagen_id, f.faelligkeit) : '';
    var wechsel = f.ok && stufenIstDatum(a.faelligkeit_zelle) && a.faelligkeit_zelle !== f.faelligkeit;
    var d = [a.angebot_am, a.erinnerung_am].filter(stufenIstDatum).sort();
    var frisch = !d.length || tageZwischen(d[d.length - 1], stichtag) <= e.antworten_lesen_bis;
    var t = enText(a.thread_id);
    var gesehen = {};
    if (t && frisch) {
      gesehen[t] = true;
      if (wechsel) aus.push(Object.assign({}, basis, { thread_id: t, vorgang: vorgangNummer(a.anlagen_id, a.faelligkeit_zelle), alt: true }));
      else aus.push(Object.assign({}, basis, { thread_id: t, vorgang: vorgang }));
    } else if (!t && d.length && frisch && vorgang && !wechsel) {
      var r0 = d[0].split('-');
      aus.push(Object.assign({}, basis, { thread_id: '', vorgang: vorgang, nur_suche: true, ab_ms: Date.UTC(+r0[0], +r0[1] - 1, +r0[2]) - 2 * 3600e3 }));
    }
    // Sicherung alte Vorgaenge lesen: Anfang
    (zeilen || []).forEach(function (r) {
      var m = r && typeof r.schluessel === 'string' ? /^(?:angebot|erinnerung)\|([^|]+)\|(\d{4}-\d{2}-\d{2})$/.exec(r.schluessel) : null;
      if (!m || m[1] !== a.anlagen_id || r.aktion !== 'versendet' || !enText(r.thread_id) || gesehen[enText(r.thread_id)]) return;
      var v = vorgangNummer(a.anlagen_id, m[2]);
      if (v === vorgang && !wechsel) return;
      if (!stufenIstDatum(r.datum) || tageZwischen(r.datum, stichtag) > e.antworten_lesen_bis) return;
      gesehen[enText(r.thread_id)] = true;
      aus.push(Object.assign({}, basis, { thread_id: enText(r.thread_id), vorgang: v, alt: true }));
    });
    // Sicherung alte Vorgaenge lesen: Ende
  });
